enum { NUM_MEMORY_SLOTS = 1 };

struct saveInfo {
    char data[104];
};

class NamesMenu {
public:
    static int FindAdjusted(int active);
};

class GenericGameSaver {
public:
    static GenericGameSaver *inst();
    void setFileInfo(saveInfo info);
    void readFile(
        int port,
        int slot,
        void *data,
        int size,
        void (*progress)(void *, int),
        void *user);
};

struct career {
    char data[0x10a48];
};

struct FEManager {
    char data[0x15690];
    bool unsaved_career;
};

class SaveLoadFrontEnd {
    char data[0x2600];
    saveInfo savedConfigs[2][15];
    NamesMenu *NameMenu;

public:
    static void SetLoadProgressGame(void *userData, int val);
    void LoadFile(int card, int filenum);
};

extern FEManager frontendmanager;
extern saveInfo loading;
extern int savePort;
extern int saveSlot;
extern career *g_career;

__asm__(".equ _16GenericGameSaver$instance, 0x0041E5B8");
__asm__(".equ setFileInfo__16GenericGameSaverG8saveInfo, 0x001E6030");
__asm__(".equ readFile__16GenericGameSaveriiPviPFPvi_vT3, 0x001E4A88");
__asm__(".equ FindAdjusted__9NamesMenui, 0x001A0808");
__asm__(".equ frontendmanager, 0x003F7728");
__asm__(".equ loading, 0x003FE2F8");
__asm__(".equ savePort, 0x0041E5AC");
__asm__(".equ saveSlot, 0x0041E5B0");
__asm__(".equ g_career, 0x00427C9C");
__asm__(".equ SetLoadProgressGame__16SaveLoadFrontEndPvi, 0x0019A238");

GenericGameSaver *GenericGameSaver::inst()
{
    return *(GenericGameSaver **)0x0041E5B8;
}

void SaveLoadFrontEnd::LoadFile(int card, int filenum)
{
    GenericGameSaver::inst()->setFileInfo(savedConfigs[NameMenu->FindAdjusted(card)][filenum]);
    loading = savedConfigs[NameMenu->FindAdjusted(card)][filenum];
    frontendmanager.unsaved_career = false;
    savePort = (card!=-1)?card/NUM_MEMORY_SLOTS:-1;
    saveSlot = (card!=-1)?card%NUM_MEMORY_SLOTS:0;
    GenericGameSaver::inst()->readFile(savePort, saveSlot , (void*)g_career,
        sizeof(*g_career),
        (SaveLoadFrontEnd::SetLoadProgressGame), (void *)this);
}
